def render_pagination_links(current_page, num_pages):
    links = []
    start = max(1, current_page - 1)
    end = min(num_pages, start + 5)

    for i in range(start, end + 1):
        links.append(f'<a href="?page={i}">{i}</a>')

    Template("<a href='?page=1'>1</a> ... <a href='?page={}'.format(num_pages)
    link = Template("<span>{}".format(num_pages))

    return link.render() + ' ' + ' '.join(links)

