import random

def get_movies(genre):
  genres_of_movies = {
    'horror': ['The Shining', 'Hereditary', 'The Conjuring'],
    'action': ['Mission: Impossible', 'John Wick', '碟中谍'],
    'comedy': ['The Hangover', 'Life Is Beautiful', 'Meet the Parents']
  }
  return genres_of_movies.get(genre, [])

def recommend_movies(genre):
  movies = get_movies(genre)

  if not movies:
    return ["No movies found for genre {}".format(genre)]

  shuffled = random.sample(movies, len(movies))
  return shuffled

