from flask import Flask, request, jsonify
import re

app = Flask(__name__)

allowed_keywords = ['pain', 'suffering', 'death', 'life']

@app.route('/chat', methods=['POST'])
def chat():
    user_message = request.form.get('message')
    user_message = re.sub(r'\s+', ' ', user_message).strip()

    chat_log = [user_message]

    response = {
        'chats': chat_log,
        'keywords': get_keywords(chat_log),
        'allowed_keywords': allowed_keywords
    }

    message = jsonify(response)
    return message

def get_keywords(chats):
    keywords = set()
    for chat in chats:
        for word in chat.split():
            keywords.add(word)
    return keywords

