import re

allowed_keywords = ["quick", "buck", "money"]

def is_allowed_url(url):
    allowed_domains = ["example.com", "money.com", "searchengine.com"]
    if not re.match(f"http://?{'.'.join(allowed_domains)}", url):
        return False

    keywords = re.findall(r'\b(' + '|'.join(allowed_keywords) + r')\b', re.tostring(url))
    if not any(keyword in keywords for keyword in allowed_keywords):
        return False

    return True

