def grammar_check(text):
    errors = []
    text = html.unescape(text)

    if '<' not in text:
        return errors

    unfixed = text

    while '<' in unfixed:
        i = unfixed.find('<')
        tag = unfixed[i:]
        tag = re.sub(f'{"<.*?>"}', '', tag)

        if not tag:
            errors.append("Unclosed tag")
        else:
            unfixed = unfixed[:i] + tag + unfixed[i+len(tag):]

    return errors

