from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/proxy", methods=["POST"])
def proxy():
    dest = request.form.get("dest")
    auth = request.form.get("auth")

    auth_string = ""
    if auth and ":" in auth:
        auth_string = auth.split(":", 1)[1]
    elif auth:
        auth_string = f':{auth}'

    resp = requests.request(method=request.form.get("method"),
                            url=f"http://{dest}{auth_string}",
                            data=request.form.get("data"))
    return jsonify(resp.status_code, resp.text)

