import re

def password_requirements(password, min_length=8,
                        required_digits=1,
                        required_uppercase=1,
                        required_lowercase=1):
    valid = True

    if len(password) < min_length:
        valid = False

    if not re.search(r'[\d]', password):
        valid = False

    if not re.search(r'[A-Z]', password):
        valid = False

    if not re.search(r'[a-z]', password):
        valid = False

    return valid

